async function gameApi(path,body,method='POST'){const r=await fetch('/api/game/'+path,{method:body===undefined?'GET':method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'A művelet nem sikerült.');return d}
