const leagueStyle={LCK:{color:'#baa3ff',label:'KOREA',caption:'LCK'},LEC:{color:'#71d6bd',label:'EMEA',caption:'LEC'},LPL:{color:'#ff858d',label:'KÍNA',caption:'LPL'},MSI:{color:'#d8a2ff',label:'TORNA',caption:'MSI'},EWC:{color:'#d8c180',label:'TORNA',caption:'EWC'},WORLDS:{color:'#e6c079',label:'VILÁGBAJNOKSÁG',caption:'Worlds'},DC:{color:'#83cde3',label:'TORNA',caption:'Demacia Cup'}};
