function leagueFacts(l,season){const phases=Hub.phases.filter(p=>p.season_id===season?.id),matches=Hub.matches.filter(m=>phases.some(p=>p.id===m.phase_id)),participants=new Set(Hub.phase_teams.filter(e=>phases.some(p=>p.id===e.phase_id)).map(e=>e.team_id));return {phases,matches,teams:participants.size}}
