let phaseDraft=null;function phaseModal(id){if(!adminOnly())return;const p=find('phases',id);phaseDraft={id:id||'',season_id:p?.season_id||adminSeason,name:p?.name||'',type:p?.type||'standings',sort_order:p?.sort_order||0,win_points:p?.win_points??1,loss_points:p?.loss_points??0,groups:Hub.phase_groups.filter(g=>g.phase_id===id).map(g=>({...g})),participants:Hub.phase_teams.filter(e=>e.phase_id===id).map(e=>({team_id:e.team_id,group_id:e.group_id}))};modal(`<h2>${p?'Fázis szerkesztése':'Új fázis'}</h2><form onsubmit="event.preventDefault();savePhase(this)"><div class="fieldgrid">${field('name','Fázis neve',`<input name="name" required value="${esc(phaseDraft.name)}">`)}<label>Típus<select name="type" onchange="phaseDraft.type=this.value;phaseExtras()">${options(Object.entries(phaseNames),phaseDraft.type)}</select></label>${field('sort_order','Sorrend',`<input name="sort_order" type="number" value="${phaseDraft.sort_order}" min="0" max="1000">`)}<div class="fieldgrid">${field('win_points','Győzelem pont',`<input type="number" name="win_points" value="${phaseDraft.win_points}" min="0" max="100">`)}${field('loss_points','Vereség pont',`<input type="number" name="loss_points" value="${phaseDraft.loss_points}" min="0" max="100">`)}</div></div><div id="phase-extras"></div><p class="formerror" id="form-error"></p><button type="submit" class="primary">Fázis mentése</button></form>`);phaseExtras()}
