async function savePhase(f){const b={season_id:phaseDraft.season_id,name:f.elements.name.value,type:f.type.value,sort_order:Number(f.sort_order.value),win_points:Number(f.win_points.value),loss_points:Number(f.loss_points.value),groups:phaseDraft.type==='groups'?phaseDraft.groups.map(({id,name})=>({id,name})):[],participants:phaseDraft.participants.map(e=>({...e,group_id:phaseDraft.type==='groups'?(e.group_id||phaseDraft.groups[0]?.id):null}))};await submitForm(f,()=>gameApi('phase'+(phaseDraft.id?'/'+phaseDraft.id:''),b,phaseDraft.id?'PATCH':'POST'),'Fázis mentve')}
