function bulkMatchModal(){
 if(!adminOnly())return;
 const phase=find('phases',adminPhase);
 if(!phase)return;
 const season=find('seasons',phase.season_id), league=find('leagues',season?.league_id);
 const exampleDate=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Budapest',year:'numeric',month:'2-digit',day:'2-digit'}).format(Date.now()+86400000);
 const placeholder=`[${league?.short_name||'LEC'}]\n#${exampleDate}\n14.00 "G2 Esports" "Karmine Corp" bo3\n17:00 FNC KOI bo5`;
 modal(`<h2>Tömeges meccsbevitel</h2><p class="muted">${esc(league?.short_name||'')} · ${esc(phase.name)} · budapesti idő</p>
 <form data-phase="${esc(phase.id)}" onsubmit="event.preventDefault();bulkMatchAction(this,event.submitter.value==='save')">
 <p class="help">Külön sorba írd a <code>[LIGA]</code> és a <code>#ÉÉÉÉ-HH-NN</code> fejlécet. Ezek a következő meccssorokra is érvényesek, amíg át nem írod őket. Többszavas csapatnévhez használj idézőjelet. A rövidítések is működnek.</p>
 <label>Meccslista<textarea name="source" required maxlength="20000" rows="10" spellcheck="false" placeholder="${esc(placeholder)}" style="width:100%;font-family:monospace;resize:vertical"></textarea></label>
 <p class="formerror" role="alert"></p><div class="bulk-preview" aria-live="polite"></div>
 <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px"><button type="submit" value="preview">Előnézet</button><button class="primary" type="submit" name="save" value="save" disabled>Meccsek mentése</button></div></form>`);
 const form=document.querySelector('#modal form');
 form.elements.source.addEventListener('input',()=>{
  form.elements.save.disabled=true;
  form.querySelector('.bulk-preview').replaceChildren();
  form.querySelector('.formerror').textContent='';
 });
}
async function bulkMatchAction(form,apply){
 const source=form.elements.source.value;
 const buttons=[...form.querySelectorAll('button[type=submit]')];
 buttons.forEach(button=>button.disabled=true);
 const error=form.querySelector('.formerror');
 error.textContent='';
 let canSave=false;
 try{
  const result=await gameApi('bulk-matches',{phase_id:form.dataset.phase,source,apply});
  if(result.applied){
   await refreshHub(false);closeModal();render();toast(result.rows.length+' meccs mentve');return;
  }
  if(form.elements.source.value!==source)return;
  const display=new Intl.DateTimeFormat('hu-HU',{timeZone:'Europe/Budapest',dateStyle:'short',timeStyle:'short'});
  const errors=result.errors.map(item=>`<li>${item.line?item.line+'. sor: ':''}${esc(item.message)}</li>`).join('');
  const rows=result.rows.map(row=>`<li><strong>${esc(row.home)} – ${esc(row.away)}</strong> · Bo${row.best_of}<br><small>${esc(display.format(new Date(row.start_at)))} · ${esc(row.league)} / ${esc(row.phase)}</small></li>`).join('');
  form.querySelector('.bulk-preview').innerHTML=`${errors?'<ul class="formerror">'+errors+'</ul>':''}${rows?'<p>'+result.rows.length+' felismert meccs</p><ol>'+rows+'</ol>':''}`;
  canSave=result.rows.length>0&&!result.errors.length;
  form.elements.save.textContent=canSave?result.rows.length+' meccs mentése':'Meccsek mentése';
 }catch(cause){error.textContent=cause.message;}
 finally{buttons[0].disabled=false;form.elements.save.disabled=!canSave;}
}
function matchModal(id){if(!adminOnly())return;const m=find('matches',id),p=find('phases',m?.phase_id||adminPhase),entries=Hub.phase_teams.filter(e=>e.phase_id===p.id),ts=entries.map(e=>team(e.team_id));const localDate=iso=>{const d=new Date(iso);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};modal(`<h2>${m?'Meccs szerkesztése':'Új meccs'}</h2><p class="muted">${esc(p.name)}</p><form onsubmit="event.preventDefault();saveMatch(this,'${id||''}','${p.id}')"><div class="fieldgrid"><label>Csapat A<select name="team_a_id" required>${options(ts.map(t=>[t.id,t.short_name+' · '+t.name]),m?.team_a_id)}</select></label><label>Csapat B<select name="team_b_id" required>${options(ts.map(t=>[t.id,t.short_name+' · '+t.name]),m?.team_b_id||ts[1]?.id)}</select></label><label>Best Of<select name="best_of">${options([1,3,5,7,9].map(n=>[n,'Bo'+n]),m?.best_of||3)}</select></label>${field('start_at','Kezdés (helyi idő)',`<input type="datetime-local" name="start_at" required value="${localDate(m?.start_at||new Date(Date.now()+86400000).toISOString())}">`)}${p.type==='groups'?`<label>Csoport<select name="group_id">${options(Hub.phase_groups.filter(g=>g.phase_id===p.id).map(g=>[g.id,g.name]),m?.group_id)}</select></label>`:''}${field('round_name','Forduló neve',`<input name="round_name" value="${esc(m?.round_name||'')}" placeholder="Alapszakasz / Semifinal / Final / 1-0">`)}${field('round_order','Forduló sorrendje',`<input type="number" name="round_order" min="0" max="1000" value="${m?.round_order||0}">`)}<label>Versenyág<select name="bracket_side">${options([['main','Fő ág'],['upper','Felső ág'],['lower','Alsó ág'],['final','Döntő']],m?.bracket_side||'main')}</select></label></div><p class="help">Az MVP-választóhoz a meccs napjára érvényes rostert elmentjük. A csapatokat előbb add a fázis résztvevőihez.</p><p class="formerror" id="form-error"></p><button type="submit" class="primary" ${ts.length<2?'disabled':''}>Meccs mentése</button></form>`)}
async function saveMatch(f,id,phase){const b={phase_id:phase,team_a_id:f.team_a_id.value,team_b_id:f.team_b_id.value,best_of:Number(f.best_of.value),start_at:new Date(f.start_at.value).toISOString(),group_id:f.group_id?.value||null,round_name:f.round_name.value,round_order:Number(f.round_order.value),bracket_side:f.bracket_side.value};await submitForm(f,()=>gameApi('match'+(id?'/'+id:''),b,id?'PATCH':'POST'),'Meccs mentve')}
function resultModal(id){if(!adminOnly())return;const m=find('matches',id),ps=Hub.match_players.filter(p=>p.match_id===id);modal(`<h2>Eredmény rögzítése</h2><p class="muted">${esc(team(m.team_a_id).name)} vs ${esc(team(m.team_b_id).name)} · Bo${m.best_of}</p><form onsubmit="event.preventDefault();saveResult(this,'${id}')"><label>Státusz<select name="status">${options(Object.entries(statusNames),m.status==='scheduled'?'completed':m.status)}</select></label><div class="fieldgrid" style="margin-top:20px">${field('score_a',esc(team(m.team_a_id).short_name),`<input type="number" name="score_a" min="0" max="${(m.best_of+1)/2}" value="${m.score_a??(m.best_of+1)/2}">`)}${field('score_b',esc(team(m.team_b_id).short_name),`<input type="number" name="score_b" min="0" max="${(m.best_of+1)/2}" value="${m.score_b??0}">`)}</div><label style="margin-top:20px">Match MVP<select name="mvp_player_id"><option value="">— Még nincs megadva —</option>${options(ps.map(p=>[p.player_id,find('players',p.player_id)?.ign+' · '+team(p.team_id).short_name]),m.mvp_player_id)}</select></label><p class="help">A mentés után a tabella és a tipp-pontszámok automatikusan újraszámolódnak. Az eredmény később javítható.</p><p class="formerror" id="form-error"></p><button class="primary" type="submit">Eredmény mentése</button></form>`)}
async function saveResult(f,id){await submitForm(f,()=>gameApi('result/'+id,{status:f.status.value,score_a:Number(f.score_a.value),score_b:Number(f.score_b.value),mvp_player_id:f.mvp_player_id.value||null}),'Eredmény mentve · tabella és pontok frissítve')}
function importPage(){if(!adminOnly())return;$('#admin-content').innerHTML=`<div class="importlayout"><div class="panel"><div class="eyebrow">ADATOK BETÖLTÉSE</div><h2>Egy JSON. Minden kapcsolat.</h2><p class="muted">Csapatok, játékosok, rosterek, évek, fázisok és meccsek tölthetők fel együtt.</p><label class="dropzone">JSON-fájl kiválasztása<input id="import-file" type="file" accept=".json,application/json" onchange="readImport(this)"><span>Legfeljebb 2 MB / 2000 alaprekord</span></label><div class="actions"><button id="validate-import" class="primary" disabled onclick="validateImport()">1. Ellenőrzés</button><button id="apply-import" disabled onclick="applyImport()">2. Importálás</button></div><div id="import-status" role="status"></div></div><div class="panel"><div class="eyebrow">MINTAFÁJLOK</div><h3>Mit tartalmazzon?</h3><ol class="importsteps"><li>Ligák és csapatok stabil ID-val, rövidítéssel, logóval.</li><li>Játékosok IGN-nel, role-lal és nemzetiséggel; a képek opcionálisak.</li><li>Roster: melyik játékos melyik csapatban, mettől meddig.</li><li>Évek és sorrendezett fázisok, résztvevőkkel és csoportokkal.</li><li>Meccsek: két csapat, Bo, időpont, opcionális eredmény és MVP.</li></ol><div class="actions"><a class="button small" href="/templates/akaras-adatok-ures.json" download>Üres sablon ↓</a><a class="button small" href="/templates/akaras-adatok-pelda.json" download>Kitöltött minta ↓</a></div><a class="button small ghost" href="/templates/JSON-utmutato.md" download style="margin-top:12px">Részletes útmutató ↓</a><p class="help">Az import új ID-kat ad hozzá. A már létező rekordokat nem írja felül, és nem töröl adatot. Éles adat helyett ne a mintacsapatokat importáld.</p></div></div>`;importData=null;importValidated=false}
async function readImport(input){importValidated=false;$('#apply-import').disabled=true;$('#validate-import').disabled=true;try{const f=input.files[0];if(!f)return;if(f.size>2000000)throw Error('A fájl legfeljebb 2 MB lehet.');importData=JSON.parse(await f.text());$('#import-status').innerHTML=`<p class="help">${esc(f.name)} betöltve. Következő lépés: ellenőrzés.</p>`;$('#validate-import').disabled=false}catch(e){$('#import-status').innerHTML=`<p class="formerror">${esc(e.message)}</p>`}}
async function validateImport(){$('#validate-import').disabled=true;try{const r=await gameApi('import',{dataset:importData,apply:false});importValidated=true;$('#import-status').innerHTML=`<div class="importsummary">${Object.entries(r.counts).map(([k,n])=>`<span>${esc(k)} <b>+${n}</b></span>`).join('')}</div>${r.warnings.map(w=>`<p class="help">${esc(w)}</p>`).join('')}<p class="positive">✓ A fájl ellenőrzése sikerült. Még nem mentettünk adatot.</p>`;$('#apply-import').disabled=false}catch(e){$('#import-status').innerHTML=`<p class="formerror">${esc(e.message)}</p>`}finally{$('#validate-import').disabled=false}}
async function applyImport(){if(!importValidated)return;$('#apply-import').disabled=true;try{await gameApi('import',{dataset:importData,apply:true});await refreshHub(false);if(typeof catalog!=='undefined')catalog=null;$('#import-status').insertAdjacentHTML('beforeend','<p class="positive">✓ Az új rekordok bekerültek az adatbázisba.</p>');importValidated=false;toast('JSON import kész')}catch(e){$('#import-status').insertAdjacentHTML('beforeend',`<p class="formerror">${esc(e.message)}</p>`);$('#apply-import').disabled=false}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});setInterval(()=>{if(document.hidden||$('#modal').open||/^#(admin|database|profile|login|register|games)/.test(location.hash))return;refreshHub()},30000);render();refreshHub();
